+void FieldLayout::remove_null_marker() {
+  LayoutRawBlock* b = first_field_block();
+  while (b != nullptr) {
+    if (b->block_kind() == LayoutRawBlock::NULL_MARKER) {
+      if (b->next_block()->block_kind() == LayoutRawBlock::EMPTY) {
