+                              field_offset + super_map->at( i * 2 + 1),
+                              super_map->at( i * 2 + 2), last_idx);
+  }
+  int len = super_map->length();
+  for (int i = num_nonoop_field * 2 + 1; i < len; i++) {
+      oop_map->append(field_offset + super_map->at(i));
