+      // Clear a cluster of oops
+      for (const zpointer* const dst_end = dst_p + map->count(); dst_p < dst_end; dst_p++) {
+        oop_clear_one(dst_p);
+        copied_bytes += sizeof(zpointer);
+      }
+      map++;
