+jlong JvmtiTagMap::find(const JvmtiHeapwalkObject& obj) const {
+  jlong tag = _hashmap->find(obj);
+  if (tag == 0 && obj.is_value()) {
+    tag = _flat_hashmap->find(obj);
+  }
+  return tag;
+}
