+// Simple FIFO.
+class DumperFlatObjectList {
+private:
+  FlatObjectIdProvider* _id_provider;
+  DumperFlatObject* _head;
+  DumperFlatObject* _tail;
+
+  void push(DumperFlatObject* obj) {
+    if (_head == nullptr) {
+      _head = _tail = obj;
+    } else {
+      assert(_tail != nullptr, "must be");
+      _tail->_next = obj;
+      _tail = obj;
+    }
+  }
