+  bool is_empty() const { return _head == nullptr; }
+
+  uintptr_t push(int offset, InlineKlass* inline_klass) {
+    uintptr_t id = _id_provider->get_id();
+    DumperFlatObject* obj = new DumperFlatObject(id, offset, inline_klass);
+    push(obj);
+    return id;
+  }
