+            }
+            size -= nlong * 8;
+            int nint = size / 4;
+            for (int j = 0; j < nint; j++) {
+                int ia = U.getInt(obj, offset);
+                result = 31 * result + ia;
+                offset += 4;
+            }
+            size -= nint * 4;
+            int nshort = size / 2;
