+            this.b = (byte)b;
+        }
+    }
+
+    SmallValue f;
+    private static final long OFFSET;
+    private static final boolean IS_FLATTENED;
+    private static final int LAYOUT;
+    static private final Unsafe U = Unsafe.getUnsafe();
