+            x = 1;
+            super();
+            sharedC1_2 = this;
+        }
+    }
+
+    static class C1 extends B1 {
+        @StrictInit
+        final int y;
+
+        C1() {
+            y = 1;
+            super(true);
+            sharedC1_1 = this;
+        }
+    }
+
+    static abstract value class E1 {
+        final int x;
+
+        E1() {
+            x = 1;
+            super();
+            sharedD1_2 = this;
+        }
+    }
+
+    static class D1 extends E1 {
+        final int y;
+        final int z;
