+                array10[0] = ((MyValueTearing)array10[0]).incrementAndCheck();
+                array11[0] = ((MyValueTearing)array11[0]).incrementAndCheck();
+                array12[0] = ((MyValueTearing)array12[0]).incrementAndCheck();
