+    static class Reader implements Runnable {
+
+        @Override
+        public void run() {
+            int scenario = 0;
+            try {
+                barrier.await();
+                Scenario.scenario0_reader();
+                barrier.await();
+                Scenario.scenario1_reader();
+                barrier.await();
+                Scenario.scenario2_reader();
+                barrier.await();
+                Scenario.scenario3_reader();
+                barrier.await();
+                Scenario.scenario4_reader();
+                barrier.await();
