+        Thread[] readers = new Thread[N_READERS];
+
+        for (int i = 0; i < N_WRITERS; i++) {
+            writers[i] = new Thread(new Writer(i), "Writer-" + i);
+            writers[i].start();
+        }
+        for (int i = 0; i < N_READERS; i++) {
+            readers[i] = new Thread(new Reader(), "Reader-" + i);
+            readers[i].start();
+        }
+
+        try {
+            System.out.println("Waiting");
