+        // Writing elements
+        for (int i = 0; i < length; i++) {
+            writeArrayElement(array, i, valueB);
+        }
+        for (int i = 0; i < length; i++) {
+            Object element = readArrayElement(array, i);
+            Asserts.assertTrue(element == valueB);
