+#include <jvmti.h>
+#include "jvmti_common.hpp"
+
+static jvmtiEnv *jvmti = nullptr;
+struct CallbackData {
+  jlong tag;
+  jint counter;
+
+  CallbackData(jlong tag): tag(tag), counter(0) {}
+};
+
+static jint JNICALL
+heap_reference_callback(jvmtiHeapReferenceKind reference_kind,
+                        const jvmtiHeapReferenceInfo* reference_info,
+                        jlong class_tag,
+                        jlong referrer_class_tag,
+                        jlong size,
+                        jlong* tag_ptr,
+                        jlong* referrer_tag_ptr,
+                        jint length,
+                        void* user_data) {
+  if (reference_kind == JVMTI_HEAP_REFERENCE_SYSTEM_CLASS) {
+    CallbackData* data = (CallbackData*)user_data;
+    data->counter++;
+    *tag_ptr = data->tag;
+  }
+  return JVMTI_VISIT_OBJECTS;
+}
+
+extern "C" JNIEXPORT jint JNICALL
+Java_HeapwalkDupClasses_tagWithFollowReferences(JNIEnv* jni, jclass clazz, jlong tag) {
+  jvmtiHeapCallbacks callbacks = {};
+  callbacks.heap_reference_callback = heap_reference_callback;
+
+  CallbackData data(tag);
+
+  jvmtiError err = jvmti->FollowReferences(0 /* filter nothing */,
+                                           nullptr /* no class filter */,
+                                           nullptr /* no initial object, follow roots */,
+                                           &callbacks,
+                                           &data);
+  check_jvmti_error(err, "FollowReferences failed");
+
+  return data.counter;
+}
+
+static jvmtiIterationControl JNICALL
+heap_root_callback(jvmtiHeapRootKind root_kind,
+                   jlong class_tag,
+                   jlong size,
+                   jlong* tag_ptr,
+                   void* user_data) {
+  if (root_kind == JVMTI_HEAP_ROOT_SYSTEM_CLASS) {
+    CallbackData* data = (CallbackData*)user_data;
+    data->counter++;
+    *tag_ptr = data->tag;
+  }
+  return JVMTI_ITERATION_CONTINUE;
+}
+
+extern "C" JNIEXPORT jint JNICALL
+Java_HeapwalkDupClasses_tagWithIterateOverReachableObjects(JNIEnv* jni, jclass clazz, jlong tag) {
+  CallbackData data(tag);
+  jvmtiError err = jvmti->IterateOverReachableObjects(heap_root_callback,
+                                                      nullptr,
+                                                      nullptr,
+                                                      &data);
+  check_jvmti_error(err, "IterateOverReachableObjects failed");
+
+  return data.counter;
+}
+
+extern "C" JNIEXPORT jobjectArray JNICALL
+Java_HeapwalkDupClasses_getObjectsWithTags(JNIEnv* jni, jclass clazz, jlong tag) {
+  jlong tags[1] = {tag};
+
+  jint count = 0;
+  jobject* objects = nullptr;
+
+  jvmtiError err = jvmti->GetObjectsWithTags(1, tags,
+                                  &count, &objects, nullptr);
+  check_jvmti_error(err, "GetObjectsWithTags failed");
+
+  jclass object_klass = jni->FindClass("java/lang/Object");
+  jobjectArray array = jni->NewObjectArray(count, object_klass, nullptr);
+
+  for (jint i = 0; i < count; i++) {
+    jni->SetObjectArrayElement(array, i, objects[i]);
+  }
+
+  deallocate(jvmti, jni, objects);
+
+  return array;
+}
+
+extern "C" JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM *vm, char *options, void *reserved) {
+  if (vm->GetEnv(reinterpret_cast<void**>(&jvmti), JVMTI_VERSION) != JNI_OK || !jvmti) {
+    LOG("Could not initialize JVMTI\n");
+    abort();
+  }
+  jvmtiCapabilities capabilities;
+  memset(&capabilities, 0, sizeof(capabilities));
+  capabilities.can_tag_objects = 1;
+  check_jvmti_error(jvmti->AddCapabilities(&capabilities), "adding capabilities");
+  return JVMTI_ERROR_NONE;
+}

