+                                           + " (instanceFilter: " + valueString(filterObject) + ")"
+                                           + ", this = " + valueString(thisObject));
+                        thisObjects.put((BreakpointRequest)event.request(), thisObject);
+                        needToResume = true;
+                        removeThisListener();
+                    }
+                }
+            };
+
+            addListener(adapter);
+
+            System.out.println("Breakpoint added: " + loc
+                               + " (instanceFilter: " + valueString(filterObject) + ")");
