+    }
+
+    static class Mutable {
+        EmptyValue o;
+        @NullRestricted
+        EmptyValue empty;
+        @NullRestricted
+        volatile EmptyValue vempty;
+
+        Mutable() {
+            empty = new EmptyValue();
+            vempty = new EmptyValue();
+            super();
+        }
+    }
+
+    @Test
+    public void emptyValueClass() {
